#include "PressedStateEngine.hpp"
#include <algorithm>
namespace RawrXD::Governance{PressureDecision PressedStateEngine::evaluate(uint64_t total,uint64_t avail,uint32_t ctx)noexcept{uint32_t pct=total?(uint32_t)(((total-avail)*100)/total):100;PressureDecision d{PressureLevel::Normal,8,false,false,false,false};if(pct>=95)d={PressureLevel::Crushed,4,true,true,true,true};else if(pct>=80||ctx>32768)d={PressureLevel::Pressed,8,true,ctx>32768,ctx>32768,false};state_.ram_pressure_pct=pct;state_.context_tokens=ctx;state_.backpressure_score=std::min<uint32_t>(100,(pct>50?pct-50:0)+(ctx>32768?25:0));state_.kv_bits=d.recommended_kv_bits;state_.emergency_halt=d.emergency_halt;return d;}AutocraticStateBlock PressedStateEngine::state()const noexcept{return state_;}void PressedStateEngine::cycle()noexcept{state_.autonomous_cycles=cycles_.fetch_add(1,std::memory_order_relaxed)+1;}}
